style.css:
@-moz-document domain("google.com") {
/* Fondo general de la página */
  body, html {
    background-color: #ffe4f2 !important;
    color: #d4006f !important;
  }

  /* Logo de Google - mantener o esconder si se quiere */
  img[alt="Google"] {
    filter: hue-rotate(320deg) brightness(1.2) !important; /* efecto rosado */
  }

  /* Cuadro del buscador */
  input.gLFyf {
    background-color: #fff0f6 !important;
    color: #d4006f !important;
    border: 2px solid #ffb6d9 !important;
    border-radius: 10px !important;
  }

  /* Botones (Buscar con Google, etc.) */
  input[type="submit"], .gNO89b, .RNmpXc {
    background-color: #ffb6d9 !important;
    color: #d4006f !important;
    border: none !important;
    border-radius: 8px !important;
  }

  /* Resultados de búsqueda */
  #search, .g, .tF2Cxc {
    background-color: #ffeef7 !important;
    color: #d4006f !important;
    border-radius: 12px !important;
    padding: 10px !important;
    margin-bottom: 10px !important;
  }

  /* Títulos de los enlaces */
  h3 {
    color: #d4006f !important;
  }

  /* URLs */
  cite, .TbwUpd {
    color: #e91e63 !important;
  }

  /* Texto de resultados */
  .VwiC3b {
    color: #c2185b !important;
  }

  /* Paginación */
  #foot, .AaVjTc {
    background-color: #ffd6ec !important;
    color: #d4006f !important;
  }

  a {
    color: #d4006f !important;
  }

  a:visited {
    color: #b0005a !important;
  }

  /* Hover sobre resultados o botones */
  *:hover {
    background-color: #ffe0f0 !important;
  }
}
